/* Mantém o catálogo completo para preservar os dados dos produtos, mas exibe somente itens com fotos válidas
   (tanto no catálogo local quanto no que vem do servidor) e só mostra categorias que tenham produtos. */
const CATALOGO_COMPLETO=P;
const temFoto=p=>(Array.isArray(IMGS[p.id])&&IMGS[p.id].some(i=>i&&i.m&&i.x&&i.l))||(typeof p.img=="string"&&p.img.trim()!=="");
function soComFotos(){P=P.filter(temFoto);CATS=Object.fromEntries(Object.entries(CATS).filter(([k])=>P.some(p=>p.c==k)))}
soComFotos();
const faqList=()=>[["Como solicito um orçamento?","Escolha um produto e clique em “Solicitar orçamento pelo WhatsApp”, ou preencha o formulário: ele abre uma conversa no WhatsApp comercial já com os seus dados."],["Os produtos podem ser personalizados?","Depende do equipamento e da viabilidade do projeto. Entre em contato para avaliar sua necessidade."],["Como funciona o Chama Garçom?","O cliente aciona o dispositivo de chamada e a equipe recebe a solicitação conforme a configuração do sistema."],["O sistema funciona em qualquer estabelecimento?","A compatibilidade deve ser avaliada conforme o produto, o ambiente e a configuração necessária."],["A empresa oferece instalação?",CFG.INSTALACAO||"A disponibilidade e as condições de instalação são confirmadas diretamente com a empresa, no orçamento."],["Como conhecer as características técnicas?","Solicite as especificações do modelo desejado ao atendimento comercial."],["Qual é o prazo de fabricação ou entrega?",CFG.ENTREGA||"O prazo depende do produto e das condições comerciais e é informado no orçamento."]];
/* ===== utilitários ===== */
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],app=$("#app");
const esc=s=>String(s).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const norm=s=>String(s).normalize("NFD").replace(/[̀-ͯ]/g,"").toLowerCase();
let waNum=String(CFG.WHATSAPP_COMERCIAL||"").replace(/\D/g,"");
const wa=t=>waNum?"https://wa.me/"+waNum+"?text="+encodeURIComponent(t):null;
const pmsg=n=>"Olá! Acessei o site da TECNO LED e gostaria de informações e orçamento para o produto: "+n+".";
const GEN="Olá! Acessei o site da TECNO LED e gostaria de informações sobre os produtos.";
function waBtn(t,msg,cls){const u=wa(msg);return u?`<a class="btn ${cls||""}" href="${u}" target="_blank" rel="noopener">${t}</a>`:`<span class="btn off ${cls||""}" role="link" aria-disabled="true" title="WhatsApp ainda não configurado">${t}</span>`}
const pendNote=()=>waNum?"":`<p class="pend">Configuração pendente (visível só até a publicação): defina WHATSAPP_COMERCIAL em CFG para ativar os botões de contato.</p>`;
const imgs=id=>{const p=byId(id),g=IMGS[id];if(p&&p.img&&!(g&&g[0]&&g[0].m==p.img))return[{x:p.img,m:p.img,l:p.img,a:p.n,g:0}];return g||[]};
const byId=id=>P.find(p=>p.id==id);
const ph=p=>`<div class="ph" role="img" aria-label="Foto real de ${esc(p.n)} ainda não disponível"><span>Foto real em breve</span><small>${esc(p.n)}</small></div>`;
function cover(p,eager){const i=imgs(p.id)[0];return i?`<img src="${i.m}" width="800" height="600" alt="${esc(i.a)}" ${eager?'fetchpriority="high"':'loading="lazy"'} decoding="async">`:ph(p)}
const paras=d=>String(d).split(/\n\n+/).map(x=>`<p>${x}</p>`).join("");
const resumo=d=>String(d).split(/\n\n+/)[0];
function card(p){return `<article class="card"><a class="pw" href="#produto-${p.id}" tabindex="-1" aria-hidden="true">${cover(p)}</a><span class="tag">${CATS[p.c]}</span><h3>${p.n}</h3><p>${resumo(p.d)}</p><ul class="vl">${p.v.map(x=>`<li>${x}</li>`).join("")}</ul><ul class="apps" aria-label="Aplicações recomendadas">${p.a.map(x=>`<li>${x}</li>`).join("")}</ul><div class="cta"><a class="btn o" href="#produto-${p.id}" aria-label="Ver detalhes: ${esc(p.n)}">Ver detalhes</a>${waBtn("Solicitar orçamento pelo WhatsApp",pmsg(p.n),"wa")}</div></article>`}
const faqH=l=>l.map(f=>`<details><summary>${f[0]}</summary><p>${f[1]}</p></details>`).join("");
const steps=`<div class="steps"><div class="card"><h3>O cliente solicita atendimento</h3><p>Usa o botão de chamada integrado ao equipamento, conforme o modelo adquirido.</p></div><div class="card"><h3>A equipe recebe a chamada</h3><p>O encaminhamento depende da configuração e dos componentes do sistema efetivamente fornecido.</p></div><div class="card"><h3>A equipe atende</h3><p>O sistema auxilia a comunicação entre cliente e equipe, de acordo com os recursos disponíveis.</p></div></div><p class="note" style="margin-top:14px">As características de funcionamento são confirmadas para cada configuração.</p>`;
const atend=`<div class="steps"><div class="card"><h3>Escolha o produto</h3><p>Navegue pelo catálogo ou use a busca. Não sabe qual escolher? Conte sua necessidade.</p></div><div class="card"><h3>Envie sua solicitação</h3><p>Pelo botão de WhatsApp ou pelo formulário, que já monta a mensagem para você.</p></div><div class="card"><h3>Receba o orçamento</h3><p>A equipe comercial responde com as informações e as condições do seu pedido.</p></div><div class="card"><h3>Combine os detalhes</h3><p>Prazo, instalação e entrega são confirmados diretamente com a empresa.</p></div></div>`;
function trustList(){const r=(l,v)=>v?`<li><strong>${l}:</strong> ${esc(v)}</li>`:"";return r("Telefone",CFG.TELEFONE)+r("E-mail",CFG.EMAIL)+r("Endereço",CFG.ENDERECO)+r("Horário de funcionamento",CFG.HORARIO)+r("Área de atendimento",CFG.AREA_ATENDIMENTO)+r("Instalação",CFG.INSTALACAO)+r("Entrega",CFG.ENTREGA)+r("Garantia",CFG.GARANTIA)}
function depoimentos(){return CFG.DEPOIMENTOS.length?`<section class="s"><h2>O que dizem nossos clientes</h2><div class="grid">${CFG.DEPOIMENTOS.map(d=>`<figure class="card" style="margin:0"><blockquote style="margin:0">“${esc(d.texto)}”</blockquote><figcaption class="tag">${esc(d.nome)}</figcaption></figure>`).join("")}</div></section>`:""}
const ctaBand=(t)=>`<section class="s"><div class="cta-band"><h2>${t||"Conte o que você precisa"}</h2><p>Nossa equipe avalia o seu projeto e envia o orçamento.</p><div class="row"><a class="btn" href="#orcamento">Preencher formulário</a>${waBtn("Chamar no WhatsApp",GEN,"wa")}</div></div></section>`;
/* ===== busca e filtros ===== */
let state={q:"",cat:"todos"};
let ME=null,CSRF=null;
const stem=w=>w.length<4?w:w.endsWith("oes")?w.slice(0,-3)+"ao":w.endsWith("eis")?w.slice(0,-3)+"el":w.endsWith("ais")?w.slice(0,-3)+"al":w.endsWith("res")?w.slice(0,-2):w.endsWith("ns")?w.slice(0,-2)+"m":w.endsWith("s")?w.slice(0,-1):w;
const words=s=>norm(s).split(/[^a-z0-9]+/).filter(Boolean).map(stem);
function filtered(){const toks=words(state.q);return P.filter(p=>{if(state.cat!="todos"&&p.c!=state.cat)return false;if(!toks.length)return true;const hay=words([p.n,p.d,CATS[p.c],p.a.join(" "),p.v.join(" "),p.kw||""].join(" ")).join(" ");return toks.every(t=>hay.includes(t))})}
const qsHash=()=>{const u=new URLSearchParams();if(state.q.trim())u.set("q",state.q.trim());if(state.cat!="todos")u.set("cat",state.cat);const s=u.toString();return "#produtos"+(s?"?"+s:"")};
function listHTML(){const l=filtered();if(l.length)return `<div class="grid gp">${l.map(card).join("")}</div>`;const q=state.q.trim();return `<div class="empty"><p><strong>Nenhum produto encontrado${q?` para “${esc(q)}”`:""}.</strong></p><p>Tente uma palavra mais simples (como “senha”, “placar” ou “garçom”) ou escolha outra categoria.</p><div class="row" style="margin-top:8px"><button class="btn o" type="button" data-clear>Limpar busca e filtros</button>${waBtn("Perguntar pelo WhatsApp",q?"Olá! Procurei por “"+q+"” no site da TECNO LED e gostaria de ajuda.":GEN,"wa")}</div></div>`}
function updateList(){if(!$("#res"))return;const n=filtered().length;$("#res").innerHTML=listHTML();$("#cnt").textContent=n+(n==1?" produto encontrado":" produtos encontrados");$$(".chip").forEach(c=>c.setAttribute("aria-pressed",c.dataset.cat==state.cat))}
let urlT;function syncUrl(now){clearTimeout(urlT);const f=()=>{if(parse().h=="produtos"&&location.hash!=qsHash())history.replaceState(null,"",qsHash())};now?f():urlT=setTimeout(f,250)}
/* ===== galeria e lightbox ===== */
const lb={items:[],i:0,op:null};
function lbOpen(items,i,op){lb.items=items;lb.i=i;lb.op=op;$("#lb").hidden=false;$("#lb").classList.add("on");document.body.style.overflow="hidden";lbShow();$("#lb .lb-x").focus()}
function lbShow(){const it=lb.items[lb.i],im=$("#lbi"),st=$("#lb .lb-st");st.classList.remove("z");im.removeAttribute("style");im.src=it.l;im.alt=it.a;$("#lbc").textContent=(lb.items.length>1?`${lb.i+1} / ${lb.items.length} · `:"")+it.a;const m=lb.items.length>1;$("#lb .lb-p").style.display=$("#lb .lb-n").style.display=m?"grid":"none";if(m)[(lb.i+1)%lb.items.length,(lb.i-1+lb.items.length)%lb.items.length].forEach(k=>{new Image().src=lb.items[k].l})}
function lbStep(d){lb.i=(lb.i+d+lb.items.length)%lb.items.length;lbShow()}
function lbClose(){if(!$("#lb").classList.contains("on"))return;$("#lb").classList.remove("on");$("#lb").hidden=true;document.body.style.overflow="";if(lb.op&&document.contains(lb.op))lb.op.focus()}
function lbZoom(){const st=$("#lb .lb-st"),im=$("#lbi");if(st.classList.toggle("z")){const w=im.getBoundingClientRect().width;im.style.width=Math.max(w*2.2,Math.min(im.naturalWidth,1600))+"px";im.style.height="auto"}else im.removeAttribute("style")}
function gallery(p){const l=imgs(p.id);if(!l.length)return `<div class="gal">${ph(p)}<p class="note">Fotos reais deste produto serão adicionadas em breve. Peça mais informações pelo WhatsApp.</p></div>`;
 return `<div class="gal" data-gal="${p.id}"><button type="button" class="main" data-open="${p.id}" data-idx="0" aria-label="Ampliar foto: ${esc(l[0].a)}"><img id="gm" src="${l[0].m}" width="800" height="600" alt="${esc(l[0].a)}" fetchpriority="high" decoding="async"><span class="zh" aria-hidden="true">Ampliar</span></button>${l.length>1?`<div class="thumbs" role="group" aria-label="Fotos do produto">${l.map((i,k)=>`<button type="button" data-thumb="${k}" aria-current="${k==0}" aria-label="Ver foto ${k+1} de ${l.length}: ${esc(i.a)}"><img src="${i.x}" width="240" height="180" alt="" loading="lazy" decoding="async"></button>`).join("")}</div>`:""}</div>`}
